// Command docscan reports Go declarations whose doc comment does not start
// with the declaration's own name — the shape a run-together comment block
// produces when a second declaration is inserted between an existing comment
// and the function it documented.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var leadName = regexp.MustCompile(`^// ([A-Za-z_]\w*)\b`)

func main() {
	root := os.Args[1]
	fset := token.NewFileSet()
	n := 0
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() || !strings.HasSuffix(path, ".go") {
			return err
		}
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			return fmt.Errorf("parsing %s: %w", path, err)
		}
		for _, d := range f.Decls {
			name, doc := declDoc(d)
			if name == "" || doc == nil {
				continue
			}
			lines := strings.Split(strings.TrimSpace(doc.Text()), "\n")
			// Reconstruct the raw first line; doc.Text() strips "// ".
			first := "// " + lines[0]
			m := leadName.FindStringSubmatch(first)
			if m == nil || m[1] == name {
				continue
			}
			// Only flag when the leading word names ANOTHER declaration in
			// this file — a comment opening with an ordinary word is fine.
			if !declares(f, m[1]) {
				continue
			}
			fmt.Printf("%s: doc for %q opens by describing %q\n", fset.Position(doc.Pos()), name, m[1])
			n++
		}
		return nil
	})
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
	fmt.Printf("%d run-together doc comment(s)\n", n)
}

func declDoc(d ast.Decl) (string, *ast.CommentGroup) {
	switch v := d.(type) {
	case *ast.FuncDecl:
		return v.Name.Name, v.Doc
	case *ast.GenDecl:
		if len(v.Specs) != 1 {
			return "", nil
		}
		switch s := v.Specs[0].(type) {
		case *ast.TypeSpec:
			return s.Name.Name, v.Doc
		case *ast.ValueSpec:
			if len(s.Names) == 1 {
				return s.Names[0].Name, v.Doc
			}
		}
	}
	return "", nil
}

func declares(f *ast.File, name string) bool {
	for _, d := range f.Decls {
		if n, _ := declDoc(d); n == name {
			return true
		}
	}
	return false
}

